from pathlib import Path
from collections import defaultdict
import pandas as pd,numpy as np,json
R=Path(__file__).resolve().parents[1];T=R/'07_tables';E=T/'phase2';S=E/'reconciled';Q=R/'06_qc/phase2'
def rd(p):return pd.read_csv(p,sep='\t',low_memory=False)
def out(d,p):d.to_csv(p,sep='\t',index=False)
h=rd(E/'PHASE2_PRE_AUDIT_EVIDENCE_MATRIX.tsv');audit=rd(T/'NOVELTY_AUDIT.tsv');m=rd(S/'FUNCTIONAL_MODULES.tsv')
# Locked external-coherence alternative; no new threshold or graph re-optimization.
external=set(h.loc[h.independent_directional_sources>0,'gene']);y=set(h.loc[h.Yeh_T_directional_support,'gene']);bulk=set(h.loc[h.Frangieh_bulk_directional_descriptive,'gene']);fm=set(h.loc[h.Frangieh_mechanistic_support,'gene'])
for col,U in [('external_directional_n',external),('Yeh_T_directional_n',y),('Frangieh_bulk_descriptive_n',bulk),('Frangieh_mechanistic_n',fm)]:m[col]=m.genes.str.split(';').map(lambda z:len(set(z)&U))
m['coherence_GO_PASS']=m.coherence_PASS;m['coherence_external_PASS']=m.external_directional_n>=3;m['coherence_PASS']=m.coherence_GO_PASS|m.coherence_external_PASS;new=m.stability_PASS&m.coherence_PASS;assert not (new & ~m.stable_coherent).any(),'new external coherent cluster requires shortlist regeneration';m['stable_coherent']=new;m['interpretation']=np.where(new,'STABLE_ANNOTATION_COHERENT','UNRESOLVED_CLUSTER');out(m,E/'FINAL_FUNCTIONAL_MODULES.tsv')
h=h.merge(audit[['gene','literature_novelty','direct_prior_immune_role','negative_audit_sufficient','primary_sources','adjudication']],on='gene',how='left',validate='one_to_one');h['literature_novelty']=h.literature_novelty.fillna('NOT_AUDITED');h['negative_audit_sufficient']=h.negative_audit_sufficient.fillna(False).astype(bool);h['direct_prior_immune_role']=h.direct_prior_immune_role.fillna(False).astype(bool)
h['independent_experimental_directional_support']=h.independent_directional_sources>0;h['external_evidence_strength']=np.where(h.Yeh_T_directional_support,'TARGETED_AUTHOR_Z_DESCRIPTIVE',np.where(h.Frangieh_bulk_directional_descriptive,'N1_PER_RATIO_DESCRIPTIVE_ONLY','NO_DIRECTIONAL_SCREEN_SUPPORT'))
h['residual_level']=h.residual_level_pre_audit
l3=h.residual & h.independent_experimental_directional_support & h.mechanistic_coherence & h.negative_audit_sufficient & ~h.direct_prior_immune_role
h.loc[l3,'residual_level']='RESIDUAL_LEVEL_3';h['NOVELTY_CANDIDATE']=l3;h['tier']=np.where(l3,'TIER_A',np.where(h.mechanistic_coherence,'TIER_B','TIER_C'));h['Joung_independent_KO_support']=False;h['Joung_support_status']='CRISPRa_VS_KO_NOT_DIRECTIONALLY_COMPARABLE'
h['tier_interpretation']=np.where(l3,'Operational cross-system candidate; evidence strength separately reported; not replicated or validated immune mechanism',np.where(h.tier=='TIER_B','B16 context-specific, module/Frangieh anchor supported; known genes explicitly retained as known','B16 context-only; external direction alone without mechanistic coherence does not make Tier B'))
# Full gene x evidence features; pathway memberships are pre-frozen and not learned from hits.
sets=rd(R/'03_metadata/MECHANISM_GENESETS.tsv').fillna('');members=defaultdict(list)
for z in sets.to_dict('records'):
 for gene in z['tested_genes'].split(';'):
  if gene:members[gene].append(z['name'])
h['known_pathway_memberships']=h.gene.map(lambda z:';'.join(sorted(members[z])))
j=rd(T/'JOUNG_DIRECTIONAL_VALIDATION.tsv').query("external_contrast=='ANTIGEN_SPECIFIC_INCREMENT'").set_index('gene_B16');b=rd(E/'FRANGIEH_BULK_VIABILITY_DESCRIPTIVE.tsv').set_index('gene');yy=rd(T/'YEH_DIRECTIONAL_SUPPORT.tsv').set_index('gene');ph=rd(T/'FRANGIEH_MECHANISTIC_PHENOTYPES.tsv');ak=rd(T/'AKANA_CROSS_MODALITY_CONTEXT.tsv')
for col in ['effect','percentile','same_direction_descriptive','opposite_direction_descriptive','tail_same_coding','tail_inverse_coding','donor_direction_consistent']:h['Joung_'+col]=h.gene.map(j[col])
for col in ['Tcell.z','NK.z','category']:h['Yeh_'+col]=h.gene.map(yy[col])
for col in ['TIL1_LFC','TIL2_LFC','TIL4_LFC','support_category']:h['Frangieh_bulk_'+col]=h.gene.map(b[col])
axis=ph.groupby('gene').axis_classification.agg(lambda x:';'.join(sorted(set(x))));h['Frangieh_axes']=h.gene.map(axis);h['Frangieh_exact_overlap']=h.gene.isin(ph.gene);h['Joung_exact_overlap']=h.gene.isin(j.index);h['Yeh_exact_overlap']=h.gene.isin(yy.index);h['Akana_exact_overlap']=h.gene.isin(ak.gene);h['Akana_support_status']=np.where(h.Akana_exact_overlap,'NOT_DIRECTIONALLY_COMPARABLE','NOT_TARGETED_OR_NOT_ONE_TO_ONE')
h['Frangieh_readout_status']=np.where(h.Frangieh_exact_overlap,np.where(h.Frangieh_mechanistic_support,'PREDEFINED_PHENOTYPE_THRESHOLD_PASS','MEASURED_NO_PREDEFINED_PHENOTYPE_PASS'),'NOT_TARGETED_OR_NO_STRICT_ORTHOLOG');h['Yeh_readout_status']=np.where(h.Yeh_exact_overlap,np.where(h.Yeh_T_directional_support,'TARGETED_DIRECTION_SUPPORT','MEASURED_THRESHOLD_OR_DIRECTION_NOT_MET'),'NOT_TARGETED_OR_NO_STRICT_ORTHOLOG')
assert len(h)==1492 and h.gene.is_unique;out(h,T/'CANDIDATE_EVIDENCE_MATRIX.tsv');out(h[h.residual],T/'RESIDUAL_GENE_CLASSIFICATION.tsv');out(h[h.tier=='TIER_A'],T/'TIER_A_CANDIDATES.tsv');out(h[h.selected_shortlist],E/'FINAL_CANDIDATE_SHORTLIST.tsv')
summary={'HC':len(h),'escape':int((h.arm=='ESCAPE_ARM').sum()),'sensitizer':int((h.arm=='SENSITIZER_ARM').sum()),'Lawson_core':int(h.known_core.sum()),'other_published_total_including_core_overlap':int(h.other_published_hit.sum()),'other_published_beyond_core':int((h.other_published_hit&~h.known_core).sum()),'dominant_known_core':int(h.dominant_known_member.sum()),'known_core_or_broad_program':int((h.dominant_known_member|h.broad_known_programs.notna()).sum()),'residual':int(h.residual.sum()),'residual_levels':{k:int((h.residual_level==k).sum()) for k in ['RESIDUAL_LEVEL_1','RESIDUAL_LEVEL_2','RESIDUAL_LEVEL_3']},'tiers':{k:int((h.tier==k).sum()) for k in ['TIER_A','TIER_B','TIER_C']},'Frangieh_overlap':int(h.Frangieh_exact_overlap.sum()),'Frangieh_phenotype':int(h.Frangieh_mechanistic_support.sum()),'Frangieh_residual_phenotype':int((h.residual&h.Frangieh_mechanistic_support).sum()),'Frangieh_bulk_directional':int(h.Frangieh_bulk_directional_descriptive.sum()),'Frangieh_bulk_residual_directional':h.loc[h.residual&h.Frangieh_bulk_directional_descriptive,'gene'].tolist(),'Yeh_T_support':int(h.Yeh_T_directional_support.sum()),'Yeh_residual_T_support':h.loc[h.residual&h.Yeh_T_directional_support,'gene'].tolist(),'Joung_overlap':int(h.Joung_exact_overlap.sum()),'Joung_residual_overlap':int((h.residual&h.Joung_exact_overlap).sum()),'Joung_direct_KO_support':0,'Akana_overlap':int(h.Akana_exact_overlap.sum()),'shortlist':int(h.selected_shortlist.sum()),'allHC_stable_coherent_modules':int(m.query("scope=='ALL_HC'").stable_coherent.sum()),'residual_stable_coherent_modules':int(m.query("scope=='RESIDUAL_ONLY'").stable_coherent.sum()),'residual_module_genes':int(h.stable_coherent_residual_module.sum()),'residual_modules_with_any_external_directional':m.query("scope=='RESIDUAL_ONLY' and stable_coherent and external_directional_n>0").module.tolist(),'allHC_stable_coherent_genes':int(h.allHC_module_stable_coherent.sum()),'tierA_genes':h.loc[h.tier=='TIER_A','gene'].tolist(),'final_verdict':'GO_MANUSCRIPT_MODERATE','primary_novel_module':'NONE_ESTABLISHED; stable residual modules lack independent directional support'}
assert summary['residual']==1354 and summary['Lawson_core']==47;assert len(summary['tierA_genes'])==0
(Q/'PHASE2_RESULTS_SUMMARY.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2));print(json.dumps(summary,ensure_ascii=False,indent=2))
